arguments.command:
cd /tmp/sv-41aeb51b4a094114aac697031229ac05 && \
# The thunk section jumps to the real code. Let's find what DWARF subprogram covers these.
python3 -c "
from elftools.elf.elffile import ELFFile

with open('libmonosgen-2.0.so.dbg', 'rb') as f:
    elf = ELFFile(f)
    dwarf = elf.get_dwarf_info()
    targets = [0x2f4b20, 0x2f4c84]

    for cu in dwarf.iter_CUs():
        for die in cu.iter_DIEs():
            if die.tag == 'DW_TAG_subprogram':
                if 'DW_AT_low_pc' in die.attributes and 'DW_AT_high_pc' in die.attributes:
                    low = die.attributes['DW_AT_low_pc'].value
                    high_attr = die.attributes['DW_AT_high_pc']
                    if high_attr.form == 'DW_FORM_addr':
                        high = high_attr.value
                    else:
                        high = low + high_attr.value
                    for t in targets:
                        if low <= t < high:
                            name = die.attributes.get('DW_AT_name')
                            if name:
                                n = name.value.decode() if isinstance(name.value, bytes) else name.value
                            else:
                                n = '(unknown)'
                            print(f'  0x{t:x} -> {n} [0x{low:x}-0x{high:x}]')
" 2>&1

